// crash-proof share/copy-result — clipboard card + download, NO Web Share API.
function dataURLToBlob(durl){ var b=atob(durl.split(',')[1]), a=new Uint8Array(b.length); for(var i=0;i<b.length;i++)a[i]=b.charCodeAt(i); return new Blob([a],{type:'image/png'}); }
function buildCardBlob(item, cb){            // SYNCHRONOUS: cb fires before this returns
  var c=document.createElement('canvas'); c.width=1200; c.height=630; var g=c.getContext('2d');
  /* draw the result card with pure 2D ops (no external <img> -> toDataURL never taints) */
  var blob=null; try{ blob=dataURLToBlob(c.toDataURL('image/png')); }catch(e){ blob=null; }
  cb(blob);                                  // synchronous toDataURL keeps us in the gesture
}
function shareText(item){ var u=(location.protocol.indexOf('http')===0)?(' '+location.href):''; return 'My pick: '+item.label+' — '+item.pct+'%'+u; } // http(s)-only URL
function clipboardFallback(item, blob){
  var txt=shareText(item);
  if(blob && navigator.clipboard && navigator.clipboard.write && typeof ClipboardItem!=='undefined'){
    try{ var p={}; p['image/png']=blob; p['text/plain']=new Blob([txt],{type:'text/plain'});
      navigator.clipboard.write([new ClipboardItem(p)]).then(function(){ status('Card copied — paste it anywhere, or download it.'); })
        .catch(function(){ textCopy(txt); }); return; }catch(e){}
  }
  textCopy(txt);
}
function textCopy(txt){ if(navigator.clipboard && navigator.clipboard.writeText){ navigator.clipboard.writeText(txt).then(function(){ status('Result copied — paste it anywhere, or download the card.'); }).catch(function(){ status('Your card is ready below — download it, or copy: '+txt); }); } else { status('Your card is ready below — download it, or copy: '+txt); } }
function doShare(item){ var blob=null; buildCardBlob(item,function(b){ blob=b; }); /* sync */ if(blob){ var a=document.getElementById('dlCard'); if(a){ a.href=URL.createObjectURL(blob); a.hidden=false; } } clipboardFallback(item, blob); } // NO navigator.share
